import { searchEntities } from "../src/lib/server/search";
import { loadDetails } from "../src/lib/server/entity-details";
import { funderId, funderDetails, member, memberDetails, memberHistoryFixture } from "./details-fixtures";

function reply(body: unknown): typeof fetch {
  return async () => Response.json(body);
}
const signal = () => new AbortController().signal;
const funder = {
  id: funderId,
  name: "Exact Funder",
  kind: "Funder",
  funder_kind: "Company",
  match_source: { kind: "name" },
};

for (const match_source of [undefined, null, {}, { kind: "other" }, { kind: "alias", name: "" }, { kind: "alias", name: "   " }, { kind: "alias" }]) {
  test(`search rejects malformed match source ${JSON.stringify(match_source)}`, async () => {
    await expect(searchEntities("Exact", signal(), reply({ entities: [funder] }), "http://api")).resolves.toHaveLength(1);
    await expect(searchEntities("Exact", signal(), reply({ entities: [{ ...funder, match_source }] }), "http://api")).rejects.toThrow("unexpected match source");
  });
}

test("search rejects alias provenance for an MP", async () => {
  const mp = { id: "1", name: "West", kind: "MP", funder_kind: null, match_source: { kind: "name" } };
  await expect(searchEntities("West", signal(), reply({ entities: [mp] }), "http://api")).resolves.toHaveLength(1);
  await expect(searchEntities("West", signal(), reply({ entities: [{ ...mp, match_source: { kind: "alias", name: "West Midlands" } }] }), "http://api")).rejects.toThrow("unexpected MP identity");
});

const funderRoute = { kind: "funder", id: funderId } satisfies Parameters<typeof loadDetails>[0];
for (const [name, body] of [
  ["missing declarations", { ...funderDetails, declarations: undefined }],
  ["invalid source timestamp", { ...funderDetails, declarations: [{ member, declaration: { ...memberHistoryFixture.declarations[0], registered_at: "broken" } }] }],
  ["missing currency total", { ...funderDetails, currencies: [{ ...funderDetails.currencies[1], amount: undefined }] }],
  ...[null, "Exact Funder", ["Exact Funder", 42]].map((aliases) => [`recorded names ${JSON.stringify(aliases)}`, { ...funderDetails, funder: { ...funderDetails.funder, aliases } }]),
]) {
  test(`details rejects ${name}`, async () => {
    expect((await loadDetails(funderRoute, signal(), reply(funderDetails), "http://api")).kind).toBe("funder");
    expect(await loadDetails(funderRoute, signal(), reply(body), "http://api")).toEqual({ kind: "error", message: "Details returned an unexpected response. Try again." });
  });
}

test("details rejects a mismatched member identity", async () => {
  const route = { kind: "member", id: "1" } satisfies Parameters<typeof loadDetails>[0];
  expect((await loadDetails(route, signal(), reply(memberDetails), "http://api")).kind).toBe("member");
  expect((await loadDetails(route, signal(), reply({ ...memberDetails, member: { ...member, id: "2" } }), "http://api")).kind).toBe("error");
});

test("details preserves decimal strings and rejects a numeric nested party amount", async () => {
  const valid = await loadDetails(funderRoute, signal(), reply(funderDetails), "http://api");
  expect(valid.kind).toBe("funder");
